NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Romans'

CHAPTERS = {
    1: {
        1: 'Paavali, Jeesuksen Kristuksen palvelija, kutsuttu apostoli, erotettu Jumalan evankeliumia varten,',
        2: 'jonka Jumala on edeltä luvannut Profeettojensa kautta Pyhissä Kirjoituksissa,',
        3: 'hänen Pojastaan – joka lihan puolesta on syntynyt Daavidin siemenestä',
        4: 'ja pyhyyden hengen puolesta kuolleistanousemisen kautta asetettu Jumalan Pojaksi voimassa – Jeesuksesta Kristuksesta, meidän Herrastamme,',
        5: 'jonka kautta olemme saaneet armon ja apostolinviran, jotta syntyisi uskon kuuliaisuus hänen nimeään kohtaan kaikissa pakanakansoissa,',
        6: 'joihin tekin, Jeesuksen Kristuksen kutsumat, kuulutte:',
        7: 'kaikille Roomassa oleville Jumalan rakkaille, kutsutuille pyhille. Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!',
        8: 'Ensiksikin kiitän Jumalaani Jeesuksen Kristuksen kautta teidän kaikkien tähden, koska teidän uskoanne julistetaan kaikessa maailmassa.',
        9: 'Sillä Jumala, jota hengessäni palvelen hänen Poikansa evankeliumilla, on todistajani, kuinka teitä lakkaamatta muistan,',
        10: 'aina rukouksissani anoen, että jo vihdoinkin, jos Jumala tahtoo, pääsisin tulemaan luoksenne.',
        11: 'Sillä ikävöin nähdä teitä voidakseni antaa teille jonkin hengellisen lahjan, että tulisitte lujiksi,',
        12: 'se on, että minäkin saisin lohdutusta teidän keskuudessanne yhteisen uskomme kautta, teidän ja minun.',
        13: 'Veljet, en tahdo teiltä salata, että jo monta kertaa olen päättänyt tulla luoksenne saadakseni jonkin hedelmän teidänkin keskuudestanne, niin kuin muidenkin pakanoiden, mutta olen ollut estetty tähän asti.',
        14: 'Kreikkalaisille ja barbaareille, viisaille ja tyhmille olen velassa.',
        15: 'Omasta puolestani siis olen halukas julistamaan evankeliumin teillekin, Roomassa asuville.',
        16: 'Sillä en häpeä Kristuksen evankeliumia, sillä se on Jumalan voima, jokaiselle uskovalle pelastukseksi, juutalaiselle ensin, sitten myös kreikkalaiselle.',
        17: 'Sillä Jumalan vanhurskaus ilmoitetaan siinä uskosta tulevana uskoa varten, niin kuin on kirjoitettu: "Vanhurskas on elävä uskosta."',
        18: 'Sillä Jumalan viha on ilmestyvä taivaasta kaikkea ihmisten jumalattomuutta ja vääryyttä vastaan, niiden, jotka pitävät totuutta vääryyden vallassa,',
        19: 'sen tähden että se, mikä Jumalasta voidaan tietää, on heillä tiedossa, sillä Jumala on sen heille ilmoittanut.',
        20: 'Sillä hänen näkymätön olemuksensa, hänen iankaikkinen voimansa ja jumalallisuutensa, ovat, kun niitä hänen teoissaan katsellaan, maailman luomisesta nähtävinä, niin etteivät he voi millään itseään puolustaa,',
        21: 'koska he, vaikka ovat tunteneet Jumalan, eivät ole häntä Jumalana kunnioittaneet eivätkä kiittäneet, vaan ovat tulleet ajatuksiltaan turhanpäiväisiksi, ja heidän ymmärtämätön sydämensä on pimentynyt.',
        22: 'Väittäessään viisaita olevansa he ovat tulleet tyhmiksi',
        23: 'ja ovat vaihtaneet katoamattoman Jumalan kirkkauden katoavan ihmisen, lintujen, nelijalkaisten ja matelijoiden kuvan kaltaiseksi.',
        24: 'Sen tähden Jumala on heidät heidän sydämensä himoissa hylännyt saastaisuuteen häpäisemään itse omat ruumiinsa,',
        25: 'nuo, jotka ovat vaihtaneet Jumalan totuuden valheeseen ja kunnioittaneet ja palvelleet luotua enemmän kuin Luojaa, joka on ylistetty iankaikkisesti, aamen.',
        26: 'Sen tähden Jumala on hylännyt heidät häpeällisiin himoihin. Sillä heidän naisensa ovat vaihtaneet luonnollisen yhteyden luonnonvastaiseen.',
        27: 'Samoin miehetkin luopuen luonnollisesta yhteydestä naisten kanssa ovat kiimoissaan syttyneet toisiinsa ja harjoittaneet miehet miesten kanssa kauheaa siveettömyyttä ja saaneet eksymyksestään itseensä sen palkan, mikä saada piti.',
        28: 'Koska heille ei kelvannut pitää kiinni Jumalan tuntemisesta, Jumala hylkäsi heidät heidän kelvottomaan mieleensä tekemään sopimattomia.',
        29: 'He ovat täynnä kaikkea vääryyttä, haureutta, pahuutta, ahneutta, häijyyttä, täynnä kateutta, murhaa, riitaa, petosta, ilkeyttä.',
        30: 'He ovat korvaan kuiskuttelijoita, panettelijoita, Jumalaa vihaavia, väkivaltaisia, ylvästelijöitä, kerskureita, kekseliäitä pahassa, vanhemmilleen tottelemattomia,',
        31: 'ymmärtämättömiä, epäluotettavia, riitaisia, rakkaudettomia ja armottomia.',
        32: 'He tuntevat Jumalan vanhurskaan säädöksen, että ne, jotka sellaista harjoittavat, ovat kuoleman ansainneet. Silti he eivät ainoastaan itse niitä tee, vaan antavat myös hyväksymisensä niille, jotka sellaista harjoittavat.',
    },
    2: {
        1: 'Sen tähden, ihminen, et voi millään itseäsi puolustaa, olitpa kuka hyvänsä, joka tuomitset. Sillä mistä toista tuomitset, siihen sinä tuomitset itsesi syylliseksi, koska sinä, joka tuomitset, teet samoja tekoja.',
        2: 'Tiedämme, että Jumalan tuomio on totuuden mukainen niille, jotka sellaista tekevät.',
        3: 'Vai luuletko, ihminen, sinä, joka tuomitset niitä, jotka sellaista tekevät, ja itse teet samoja tekoja, että sinä pääset Jumalan tuomiota pakoon?',
        4: 'Vai halveksitko hänen hyvyytensä, kärsivällisyytensä ja pitkämielisyytensä runsautta, etkä tiedä, että Jumalan hyvyys ajaa sinua mielenmuutokseen?',
        5: 'Kovuudellasi ja katumattomalla sydämelläsi sinä kokoat päällesi vihaa vihan ja Jumalan vanhurskaan tuomion ilmestymisen päiväksi,',
        6: 'hänen, "joka maksaa kullekin hänen tekojensa mukaan":',
        7: 'iankaikkisen elämän niille, jotka hyvässä työssä kestävinä etsivät kirkkautta, kunniaa ja katoamattomuutta,',
        8: 'mutta kiivaus ja viha tulevat niiden osaksi, jotka ovat riidanhaluisia eivätkä tottele totuutta, vaan tottelevat vääryyttä.',
        9: 'Tuska ja ahdistus jokaisen ihmisen sielulle, joka tekee pahaa, juutalaiselle ensin, sitten myös kreikkalaiselle,',
        10: 'mutta kirkkaus, kunnia ja rauha jokaiselle, joka tekee sitä, mikä on hyvää, juutalaiselle ensin, sitten myös kreikkalaiselle!',
        11: 'Sillä Jumalan edessä ei ole puolueellisuutta.',
        12: 'Sillä kaikki ne, jotka ilman lakia ovat syntiä tehneet, myös ilman lakia joutuvat kadotukseen, ja kaikki ne, jotka lain piirissä ollen ovat syntiä tehneet, lain mukaan tuomitaan.',
        13: 'Eivät näet lain kuulijat ole vanhurskaita Jumalan edessä, vaan lain noudattajat vanhurskautetaan.',
        14: 'Sillä kun pakanat, joilla ei lakia ole, luonnostaan tekevät, mitä laki vaatii, niin he, vaikka heillä ei lakia ole, ovat itse itselleen laki',
        15: 'ja osoittavat, että lain teot ovat kirjoitetut heidän sydämiinsä, kun heidän omatuntonsa yhdessä todistaa ja heidän ajatuksensa keskenään syyttävät tai myös puolustavat heitä –',
        16: 'sinä päivänä, jona Jumala on tuomitseva ihmisten salaisuudet Jeesuksen Kristuksen kautta minun evankeliumini mukaan.',
        17: 'Katso, sinä sanot itseäsi juutalaiseksi ja luotat lakiin ja kerskut Jumalassa',
        18: 'ja tunnet hänen tahtonsa ja laista opetuksen saatuasi tutkit, mikä on parasta,',
        19: 'ja luulet kykeneväsi olemaan sokeiden taluttaja, pimeydessä olevien valo,',
        20: 'ymmärtämättömien kasvattaja, alaikäisten opettaja, sinulla kun on laissa tiedon ja totuuden muoto:',
        21: 'niin sinäkö, joka toista opetat, et itseäsi opeta; joka julistat, ettei saa varastaa, itse varastat;',
        22: 'joka sanot, ettei saa tehdä huorin, itse teet huorin; joka kauhistut epäjumalia, kuitenkin olet temppelin ryöstäjä;',
        23: 'joka laista kerskaat, häpäiset lainrikkomisella Jumalaa?',
        24: 'Sillä "teidän tähtenne Jumalan nimi tulee pilkatuksi pakanoiden keskuudessa", kuten on kirjoitettu.',
        25: 'Ympärileikkaus tosin on hyödyllinen, jos noudatat lakia, mutta jos olet lainrikkoja, niin ympärileikkauksesi on tullut ympärileikkaamattomuudeksi.',
        26: 'Jos siis ympärileikkaamaton noudattaa lain säädöksiä, eikö hänen ympärileikkaamattomuutensa ole luettava ympärileikkaukseksi?',
        27: 'Ja luonnostaan ympärileikkaamaton, joka täyttää lain, on tuomitseva sinut, joka lainkirjaiminesi ja ympärileikkauksinesi olet lainrikkoja.',
        28: 'Sillä ei se ole juutalainen, joka vain ulkonaisesti on juutalainen, eikä ympärileikkaus se, joka tapahtuu ulkonaisesti lihassa,',
        29: 'vaan se on juutalainen, joka salassa on juutalainen, ja oikea ympärileikkaus on sydämen ympärileikkaus Hengessä, ei kirjaimessa, ja hän saa kiitoksensa, ei ihmisiltä, vaan Jumalalta.',
    },
    3: {
        1: 'Mitä etuja siis on juutalaisilla tai mitä hyötyä ympärileikkauksesta?',
        2: 'Paljonkin, kaikin tavoin, ennen kaikkea se, että heille on uskottu Jumalan sanat.',
        3: 'Mutta kuinka? Jos jotkut ovat olleet epäuskoisia, eihän heidän epäuskonsa ole tekevä Jumalan uskollisuutta tyhjäksi?',
        4: 'Ei ikinä! Olkoon Jumala totinen, mutta jokainen ihminen valehtelija, niin kuin kirjoitettu on: "Että sinut julistettaisiin vanhurskaaksi sanoissasi ja että voittaisit, kun kanssasi käydään oikeutta."',
        5: 'Mutta jos meidän vääryytemme todistaa Jumalan vanhurskautta, mitä sanomme? Ei kaiketi Jumala ole väärä, kun hän rankaisee vihassaan? Puhun ihmisten tavalla.',
        6: 'Ei ikinä! Sillä kuinka Jumala silloin on tuomitseva maailman?',
        7: 'Sillä jos Jumalan totuus on minun valheeni kautta tullut runsaammin hänen kirkkaudekseen, miksi sitten minutkin vielä tuomitaan syntisenä?',
        8: 'Ja miksi ei ole, niin kuin herjaten syyttävät meidän tekevän ja kuten muutamat väittävät meidän sanovan: "Tehkäämme pahaa, että siitä tulisi hyvää"? Niille tuleva tuomio on oikea.',
        9: 'Miten siis on? Olemmeko parempia? Emme suinkaan. Olemme edellä osoittaneet, että kaikki, niin hyvin juutalaiset kuin kreikkalaiset, ovat synnin alla,',
        10: 'niin kuin kirjoitettu on: "Ei ole ketään vanhurskasta, ei ainoatakaan,',
        11: 'ei ole ketään ymmärtäväistä, ei ketään, joka etsii Jumalaa.',
        12: 'Kaikki ovat poikenneet pois, kaikki tyynni kelvottomiksi käyneet. Ei ole ketään, joka tekee sitä, mikä hyvää on, ei yhden yhtäkään.',
        13: 'Heidän kurkkunsa on avoin hauta, kielellään he pettävät, kyyn myrkkyä on heidän huultensa alla.',
        14: 'Heidän suunsa on täynnä kirousta ja katkeruutta.',
        15: 'Heidän jalkansa ovat nopeat vuodattamaan verta.',
        16: 'Hävitystä ja kurjuutta on heidän teillään,',
        17: 'eivätkä he tunne rauhan tietä.',
        18: 'Jumalan pelko ei ole heidän silmiensä edessä."',
        19: 'Mutta tiedämme, että kaiken, minkä laki sanoo, sen se puhuu niille, jotka ovat lain alla, että jokainen suu tukittaisiin ja koko maailma tulisi syylliseksi Jumalan edessä,',
        20: 'sen tähden, ettei mitään lihaa julisteta hänen edessään vanhurskaaksi lain teoista, sillä lain kautta tulee synnintunto.',
        21: 'Mutta nyt Jumalan vanhurskaus, josta Laki ja Profeetat todistavat, on ilmoitettu ilman lakia,',
        22: 'se Jumalan vanhurskaus, joka uskon kautta Jeesukseen Kristukseen tulee kaikkiin ja kaikille, jotka uskovat, sillä ei ole yhtään erotusta.',
        23: 'Sillä kaikki ovat syntiä tehneet ja ovat Jumalan kirkkautta vailla',
        24: 'ja saavat lahjaksi vanhurskauden hänen armostaan sen lunastuksen kautta, joka on Kristuksessa Jeesuksessa,',
        25: 'jonka Jumala on asettanut armoistuimeksi uskon kautta hänen vereensä osoittaakseen vanhurskautensa, koska hän oli jättänyt rankaisematta ennen tehdyt synnit',
        26: 'jumalallisessa kärsivällisyydessään, osoittaakseen vanhurskautensa nykyajassa, sen, että hän itse on vanhurskas ja julistaa vanhurskaaksi sen, jolla on usko Jeesukseen.',
        27: 'Missä siis on kerskaaminen? Se on suljettu pois. Minkä lain kautta? Tekojenko lain? Ei, vaan uskon lain kautta.',
        28: 'Niin päätämme siis, että ihminen julistetaan vanhurskaaksi uskon kautta, ilman lain tekoja.',
        29: 'Vai onko Jumala yksistään juutalaisten Jumala? Eikö pakanoidenkin? On pakanoidenkin,',
        30: 'koskapa Jumala on yksi, joka julistaa ympärileikatut vanhurskaiksi uskosta ja ympärileikkaamattomat uskon kautta.',
        31: 'Teemmekö siis lain mitättömäksi uskon kautta? Ei ikinä! Vaan vahvistamme lain.',
    },
    4: {
        1: 'Mitä siis sanomme isämme Aabrahamin saavuttaneen lihan mukaan?',
        2: 'Sillä jos Aabraham on teoista julistettu vanhurskaaksi, hänellä on kerskaamista, mutta ei Jumalan edessä.',
        3: 'Sillä mitä Raamattu sanoo? "Aabraham uskoi Jumalaa, ja se luettiin hänelle vanhurskaudeksi."',
        4: 'Mutta työtä tekevälle ei lueta palkkaa armosta, vaan ansiosta,',
        5: 'mutta sille, joka ei tee työtä, vaan uskoo häneen, joka julistaa jumalattoman vanhurskaaksi, luetaan hänen uskonsa vanhurskaudeksi.',
        6: 'Samoin myös Daavid ylistää autuaaksi sitä ihmistä, jolle Jumala lukee vanhurskauden ilman tekoja:',
        7: '"Autuaita ne, joiden lain rikkomiset ovat anteeksi annetut ja joiden synnit ovat peitetyt!',
        8: 'Autuas se mies, jolle Herra ei lue syntiä!"',
        9: 'Koskeeko sitten tämä autuaaksi ylistäminen ainoastaan ympärileikattuja vai eikö ympärileikkaamattomiakin? Sanommehan: "Aabrahamille luettiin usko vanhurskaudeksi."',
        10: 'Kuinka se sitten siksi luettiin? Hänen ollessaan ympärileikattuna vai ympärileikkaamattomana? Ei ympärileikattuna, vaan ympärileikkaamattomana.',
        11: 'Hän sai ympärileikkauksen merkin sinetiksi sille uskon vanhurskaudelle, joka hänellä oli ympärileikkaamattomana, että hän olisi kaikkien isä, jotka uskovat ympärileikkaamattomina, jotta vanhurskaus luettaisiin heillekin,',
        12: 'ja että hän olisi myös ympärileikattujen isä, niiden, jotka eivät ainoastaan ole ympärileikattuja, vaan myös vaeltavat sen uskon jälkiä, mikä meidän isällämme Aabrahamilla oli ympärileikkaamattomana.',
        13: 'Sillä se lupaus, että Aabraham perii maailman, ei tullut hänelle eikä hänen siemenelleen lain kautta, vaan uskonvanhurskauden kautta.',
        14: 'Sillä jos perillisiä ollaan lain nojalla, usko on tyhjäksi tehty ja lupaus on mitätön.',
        15: 'Sillä laki saa aikaan vihaa, mutta missä lakia ei ole, siellä ei ole rikkomistakaan.',
        16: 'Sen tähden se on uskosta, että se olisi armosta ja että lupaus olisi luja kaikelle siemenelle, ei ainoastaan sille, joka on lain piiristä, vaan myös sille, jolla on Aabrahamin usko, hänen, joka on meidän kaikkien isä',
        17: '– kuten on kirjoitettu: "Monen kansan isäksi olen sinut asettanut" – sen Jumalan edessä, johon hän uskoi ja joka tekee kuolleet eläviksi ja kutsuu olemattomat olemassa olevina.',
        18: 'Aabraham uskoi toivon varassa, kun mitään toivoa ei ollut, tulevansa monen kansan isäksi, tämän sanan mukaan: "Niin on siemenesi oleva",',
        19: 'eikä hän heikentynyt uskossa, vaikka näki, että hänen ruumiinsa oli kuoleutunut – sillä hän oli jo noin satavuotias – ja että Saaran kohtu oli kuoleutunut,',
        20: 'mutta Jumalan lupausta hän ei epäillyt epäuskossa, vaan vahvistui uskossa antaen kunnian Jumalalle,',
        21: 'ja oli täysin varma siitä, että minkä Jumala on luvannut, sen hän voi myös tehdä.',
        22: 'Sen tähden se luettiinkin hänelle vanhurskaudeksi.',
        23: 'Mutta ei ainoastaan hänen tähtensä ole kirjoitettu, että se hänelle luettiin,',
        24: 'vaan myös meidän tähtemme, joille se on luettava, meille, jotka uskomme häneen, joka kuolleista herätti Jeesuksen, meidän Herramme,',
        25: 'joka on alttiiksi annettu meidän [lain] rikkomisiemme tähden ja kuolleista herätetty meidän vanhurskauttamisemme tähden.',
    },
    5: {
        1: 'Koska meidät on siis uskosta vanhurskaiksi julistettu, meillä on rauha Jumalan kanssa meidän Herramme Jeesuksen Kristuksen kautta,',
        2: 'jonka kautta myös olemme uskossa saaneet pääsyn tähän armoon, jossa seisomme, ja kerskauksenamme on Jumalan kirkkauden toivo',
        3: 'eikä vain se, vaan kerskaamme myös ahdistuksissa, sillä tiedämme, että ahdistus saa aikaan kärsivällisyyttä,',
        4: 'mutta kärsivällisyys harjaantumista, ja harjaantuminen toivoa,',
        5: 'mutta toivo ei saata häpeään, sillä Jumalan rakkaus on vuodatettu sydämiimme Pyhän Hengen kautta, joka on meille annettu.',
        6: 'Sillä meidän vielä ollessamme heikkoja kuoli Kristus oikeaan aikaan jumalattomien edestä.',
        7: 'Tuskin näet kukaan kuolee jonkun vanhurskaan edestä. Hyvän edestähän joku mahdollisesti uskaltaakin kuolla.',
        8: 'Mutta Jumalan rakkaus meitä kohtaan on siinä, että Kristus, kun vielä olimme syntisiä, kuoli meidän edestämme.',
        9: 'Paljon ennemmin siis nyt, kun olemme julistetut vanhurskaiksi hänen veressään, pelastumme hänen kauttaan vihasta.',
        10: 'Sillä jos tulimme sovitetuiksi Jumalan kanssa hänen Poikansa kuoleman kautta, kun vielä olimme vihan alaisia, paljon ennemmin pelastumme hänen elämänsä kautta nyt, kun olemme sovitetut,',
        11: 'emmekä ainoastaan sovitetut, vaan vieläpä Jumala on kerskauksemme Herramme Jeesuksen Kristuksen kautta, jonka kautta nyt olemme sovituksen saaneet.',
        12: 'Sen tähden, niin kuin yhden ihmisen kautta synti tuli maailmaan, ja synnin kautta kuolema, samoin kuolema on tullut kaikkiin ihmisiin, koska kaikki ovat syntiä tehneet –',
        13: 'sillä jo ennen lakiakin oli synti maailmassa, mutta syntiä ei lueta, missä lakia ei ole.',
        14: 'Kuitenkin kuolema hallitsi Aadamista Moosekseen asti niitäkin, jotka eivät olleet tehneet syntiä samanlaisella rikkomisella kuin Aadam, joka on sen esikuva, joka oli tuleva.',
        15: 'Mutta armolahjan laita ei ole samoin kuin rikkomisen, sillä joskin yhden rikkomisen kautta monet ovat kuolleet, niin paljoa ennemmin on Jumalan armo ja lahja yhden ihmisen, Jeesuksen Kristuksen, armon kautta ylenpalttisesti tullut monien osaksi.',
        16: 'Eikä lahjan laita ole, niin kuin on sen, mikä tuli yhden synnintekijän kautta, sillä tuomio tuli yhdestä ihmisestä kadotukseksi, mutta armolahja on tullut monien rikkomisista vanhurskauttamiseksi.',
        17: 'Ja jos yhden ihmisen lankeamisen tähden kuolema on hallinnut yhden kautta, niin paljoa ennemmin ne, jotka saavat armon ja vanhurskauden lahjan runsauden, tulevat elämässä hallitsemaan yhden, Jeesuksen Kristuksen, kautta.',
        18: 'Niinpä siis, samoin kuin yhden ihmisen lankeemus on tullut kaikille ihmisille kadotustuomioksi, niin myös yhden ihmisen vanhurskaus on tullut kaikille ihmisille elämän vanhurskauttamiseksi,',
        19: 'sillä niin kuin yhden ihmisen tottelemattomuuden kautta monet ovat luetut syntisiksi, niin myös yhden kuuliaisuuden kautta monet ovat luetut vanhurskaiksi.',
        20: 'Mutta laki tuli väliin, että rikkominen tulisi suureksi; mutta missä synti on tullut suureksi, siinä armo on tullut ylenpalttiseksi,',
        21: 'että niin kuin synti on hallinnut kuolemassa, samoin armokin hallitsisi vanhurskauden kautta iankaikkiseksi elämäksi Jeesuksen Kristuksen, meidän Herramme, kautta.',
    },
    6: {
        1: 'Mitä siis sanomme? Onko meidän pysyttävä synnissä, että armo tulisi suureksi?',
        2: 'Ei ikinä! Kuinka me, jotka olemme kuolleet pois synnistä, vielä eläisimme siinä?',
        3: 'Vai ettekö tiedä, että kaikki, jotka olemme kastetut Kristukseen Jeesukseen, olemme hänen kuolemaansa kastetut?',
        4: 'Olemme siis yhdessä hänen kanssaan haudatut kasteen kautta kuolemaan, että kuten Kristus herätettiin kuolleista Isän kirkkauden kautta, mekin samalla tavalla vaeltaisimme uudessa elämässä.',
        5: 'Sillä jos olemme hänen kanssaan kasvaneet yhteen yhtäläisessä kuolemassa, samoin olemme myös yhtäläisessä ylösnousemuksessa,',
        6: 'koska tiedämme, että vanha ihmisemme on hänen kanssaan ristiinnaulittu, jotta synnin ruumis kukistettaisiin, että me emme enää syntiä palvelisi,',
        7: 'sillä se, joka on kuollut, on vanhurskautunut pois synnistä.',
        8: 'Mutta jos olemme kuolleet Kristuksen kanssa, uskomme, että tulemme myös elämään hänen kanssaan,',
        9: 'tietäen, että Kristus, sitten kun hänet herätettiin kuolleista, ei enää kuole. Kuolemalla ei ole enää valtaa häneen.',
        10: 'Sillä minkä hän kuoli, sen hän kerta kaikkiaan kuoli pois synnistä, mutta minkä hän elää, sen hän elää Jumalalle.',
        11: 'Samalla tavalla tekin pitäkää itsenne synnille kuolleina, mutta Jumalalle elävinä Kristuksessa Jeesuksessa meidän Herrassamme.',
        12: 'Älköön siis synti hallitko teidän kuolevaisessa ruumiissanne, niin että olette kuuliaisia sen himoille,',
        13: 'älkääkä antako jäseniänne vääryyden aseiksi synnille, vaan antakaa itsenne kuolleista eläviksi tulleina Jumalalle ja jäsenenne vanhurskauden aseiksi Jumalalle.',
        14: 'Sillä synti ei ole teitä vallitseva, koska ette ole lain alla, vaan armon alla.',
        15: 'Kuinka siis on? Saammeko tehdä syntiä, koska emme ole lain alla, vaan armon alla? Ei ikinä!',
        16: 'Ettekö tiedä, että kenen orjiksi, ketä tottelemaan, te antaudutte, sen orjia te olette, jota te tottelette, joko synnin orjia kuolemaksi tai kuuliaisuuden vanhurskaudeksi?',
        17: 'Mutta kiitos Jumalalle, että te, jotka olitte synnin orjia, nyt olette tulleet sydämestänne kuuliaisiksi sille opin muodolle, jonka johtoon teidät on annettu,',
        18: 'ja että te synnistä vapautettuina olette tulleet vanhurskauden orjiksi!',
        19: 'Puhun ihmisten tavalla teidän lihanne heikkouden tähden. Sillä niin kuin ennen annoitte jäsenenne saastaisuuden ja laittomuuden orjiksi laittomuuteen, antakaa nyt jäsenenne vanhurskauden orjiksi pyhitykseen.',
        20: 'Sillä kun olitte synnin orjia, olitte vapaita vanhurskaudesta.',
        21: 'Minkä hedelmän te siitä silloin saitte? Sen, jota nyt häpeätte. Sillä sen loppu on kuolema.',
        22: 'Mutta nyt, kun olette synnistä vapautetut ja Jumalan orjiksi tulleet, teidän hedelmänne on pyhitys, ja sen loppu on iankaikkinen elämä.',
        23: 'Sillä synnin palkka on kuolema, mutta Jumalan armolahja on iankaikkinen elämä Kristuksessa Jeesuksessa, meidän Herrassamme.',
    },
    7: {
        1: 'Vai ettekö tiedä, veljet – puhun lain tunteville – että laki vallitsee ihmistä koko sen ajan, jonka hän elää?',
        2: 'Niinpä laki sitoo naimisissa olevan naisen hänen elossa olevaan mieheensä, mutta jos mies kuolee, vaimo on vapaa tästä miehen laista.',
        3: 'Sen tähden hän saa avionrikkojan nimen, jos miehensä eläessä menee toiselle miehelle. Mutta jos mies kuolee, hän on vapaa laista, niin ettei hän ole avionrikkoja, jos menee toiselle miehelle.',
        4: 'Niin, veljeni, teidätkin on kuoletettu laista Kristuksen ruumiin kautta tullaksenne toisen omiksi, hänen, joka on kuolleista herätetty, jotta kantaisimme hedelmää Jumalalle.',
        5: 'Sillä kun olimme lihan vallassa, niin synnin himot, jotka laki herättää, vaikuttivat jäsenissämme, niin että kannoimme hedelmää kuolemalle,',
        6: 'mutta nyt olemme vapaat laista ja kuolleet pois siitä, mikä piti meidät vankeina, niin että palvelemme Jumalaa Hengen uudessa tilassa emmekä kirjaimen vanhassa.',
        7: 'Mitä siis sanomme? Onko laki syntiä? Ei ikinä! Mutta syntiä en olisi tullut tuntemaan muuten kuin lain kautta. Sillä en olisi tiennyt himosta, ellei laki olisi sanonut: "Älä himoitse."',
        8: 'Mutta kun synti otti käskystä aiheen, se herätti minussa kaikkia himoja, sillä ilman lakia synti on kuollut.',
        9: 'Minä taas elin ennen ilman lakia, mutta kun käsky tuli, synti sitä vastoin virkosi,',
        10: 'mutta minä kuolin. Kävi ilmi, että käsky, jonka oli määrä olla minulle elämäksi, olikin minulle kuolemaksi.',
        11: 'Sillä kun synti otti käskystä aiheen, se petti minut ja kuoletti minut käskyn kautta.',
        12: 'Niin, laki on kuitenkin pyhä ja käsky pyhä, vanhurskas ja hyvä.',
        13: 'Onko siis hyvä tullut minulle kuolemaksi? Pois se! Vaan synti, jotta se synniksi nähtäisiin, on hyvän kautta tuottanut minulle kuoleman, että synti tulisi ylenmäärin synnilliseksi käskyn kautta.',
        14: 'Sillä tiedämme, että laki on hengellinen, mutta minä olen lihallinen, myyty synnin alle.',
        15: 'Sillä en tunne omakseni sitä, mitä teen, sillä en toteuta sitä, mitä tahdon, vaan mitä vihaan, sitä teen.',
        16: 'Mutta jos teen sitä, mitä en tahdo, niin myönnän, että laki on hyvä.',
        17: 'Niin nyt sitä en enää tee minä, vaan synti, joka minussa asuu.',
        18: 'Sillä tiedän, ettei minussa, se on minun lihassani, asu mitään hyvää. Tahtoa minussa on, mutta hyvän toteuttamista en itsestäni löydä,',
        19: 'sillä sitä hyvää, mitä tahdon, en tee, vaan sitä pahaa, mitä en tahdo, teen.',
        20: 'Jos minä siis teen sitä, mitä en tahdo, niin sen tekijä en enää ole minä, vaan synti, joka minussa asuu.',
        21: 'Huomaan siis itsessäni, minä, joka tahdon hyvää tehdä, sen lain, että paha on minussa läsnä,',
        22: 'sillä sisäisen ihmiseni puolesta iloitsen Jumalan laista,',
        23: 'mutta jäsenissäni näen toisen lain, joka sotii mieleni lakia vastaan ja pitää minut vangittuna synnin laissa, joka on jäsenissäni.',
        24: 'Minä kurja ihminen, kuka pelastaa minut tästä kuoleman ruumiista?',
        25: 'Kiitos Jumalalle Jeesuksen Kristuksen, meidän Herramme, kautta! Minä siis tällaisena palvelen mielellä Jumalan lakia, mutta lihalla synnin lakia.',
    },
    8: {
        1: 'Nyt ei siis ole mitään kadotustuomiota niille, jotka Kristuksessa Jeesuksessa ovat, niille, jotka eivät vaella lihan mukaan, vaan Hengen mukaan.',
        2: 'Sillä elämän hengen laki Kristuksessa Jeesuksessa on vapauttanut minut synnin ja kuoleman laista.',
        3: 'Sillä mihin laki oli voimaton, koska se oli lihan kautta tullut heikoksi, sen Jumala teki lähettämällä oman Poikansa syntisen lihan kaltaisuudessa ja synnin tähden ja tuomitsi synnin lihassa,',
        4: 'että lain vanhurskaus täytettäisiin meissä, jotka emme vaella lihan mukaan, vaan Hengen mukaan.',
        5: 'Sillä niillä, jotka elävät lihan mukaan, on lihan mieli, mutta niillä, jotka elävät Hengen mukaan, on Hengen mieli.',
        6: 'Sillä lihan mieli on kuolema, mutta Hengen mieli on elämä ja rauha,',
        7: 'sen tähden että lihan mieli on vihollisuus Jumalaa vastaan, sillä se ei alistu Jumalan lain alle, eikä se voikaan.',
        8: 'Ne, jotka ovat lihan vallassa, eivät voi olla Jumalalle otollisia.',
        9: 'Mutta te ette ole lihan vallassa, vaan Hengen, jos kerran Jumalan Henki asuu teissä. Mutta se, jolla ei ole Kristuksen Henkeä, ei ole hänen omansa.',
        10: 'Mutta jos Kristus on teissä, niin ruumis tosin on kuollut synnin tähden, mutta henki on elämä vanhurskauden tähden.',
        11: 'Jos nyt hänen Henkensä, hänen, joka herätti Jeesuksen kuolleista, asuu teissä, niin hän, joka herätti kuolleista Kristuksen Jeesuksen, on tekevä eläviksi myös teidän kuolevaiset ruumiinne Henkensä kautta, joka teissä asuu.',
        12: 'Niin siis, veljet, olemme nyt velassa, mutta emme lihalle lihan mukaan elääksemme.',
        13: 'Sillä jos lihan mukaan elätte, on teidän kuoltava, mutta jos Hengellä kuoletatte ruumiin teot, on teillä oleva elämä.',
        14: 'Sillä kaikki, joita Jumalan Henki kuljettaa, ovat Jumalan lapsia.',
        15: 'Sillä ette ole ottaneet vastaan orjuuden henkeä ollaksenne jälleen pelossa, vaan te olette ottaneet vastaan lapseuden Hengen, jossa huudamme: "Abba! Isä!"',
        16: 'Henki itse todistaa henkemme kanssa, että olemme Jumalan lapsia.',
        17: 'Mutta jos olemme lapsia, olemme myös perillisiä, Jumalan perillisiä ja Kristuksen kanssaperillisiä, jos kerran yhdessä hänen kanssaan kärsimme, että yhdessä myös kirkastuisimme.',
        18: 'Sillä päätän, että tämän nykyisen ajan kärsimykset eivät ole verrattavissa tulevaan kirkkauteen, joka on ilmestyvä meihin.',
        19: 'Sillä luomakunnan harras ikävöiminen odottaa Jumalan lasten ilmestymistä.',
        20: 'Sillä luomakunta on alistettu turhuuden alle – ei omasta tahdostaan, vaan alistajan – toivon varaan,',
        21: 'koska itse luomakuntakin on tuleva vapautetuksi turmeluksen orjuudesta Jumalan lasten kirkkauden vapauteen.',
        22: 'Sillä tiedämme, että koko luomakunta yhdessä huokaa ja on synnytystuskissa tähän asti,',
        23: 'eikä ainoastaan se, vaan myös me, joilla on Hengen esikoislahja, mekin huokaamme sisimmässämme odottaen lapseksi ottamista, ruumiimme lunastusta.',
        24: 'Sillä toivossa olemme pelastetut, mutta toivo, jonka näkee täyttyneen, ei ole mikään toivo. Kuinka kukaan toivoo sitä, minkä näkee?',
        25: 'Mutta jos toivomme, mitä emme näe, odotamme sitä kärsivällisyydellä.',
        26: 'Samoin myös Henki auttaa heikkouksissamme. Sillä emme tiedä, mitä rukoilisimme, kuten pitää, mutta Henki itse rukoilee puolestamme sanomattomin huokauksin.',
        27: 'Mutta sydänten tutkija tietää, mikä Hengen mieli on, sillä Henki rukoilee Jumalan tahdon mukaan pyhien edestä.',
        28: 'Mutta tiedämme, että kaikki yhdessä vaikuttaa niiden parhaaksi, jotka Jumalaa rakastavat, niiden, jotka hänen päätöksensä mukaan ovat kutsutut.',
        29: 'Sillä ne, jotka hän on ennalta omikseen tuntenut, hän on myös ennalta määrännyt Poikansa kuvan kaltaisiksi, että hän olisi esikoinen monien veljien joukossa.',
        30: 'Mutta ne, jotka hän on ennalta määrännyt, hän on myös kutsunut. Ne, jotka hän on kutsunut, hän on myös julistanut vanhurskaiksi, mutta ne, jotka hän on julistanut vanhurskaiksi, hän on myös kirkastanut.',
        31: 'Mitä siis tähän sanomme? Jos Jumala on puolellamme, kuka on meitä vastaan?',
        32: 'Hän, joka ei säästänyt omaa Poikaansakaan, vaan antoi hänet alttiiksi kaikkien meidän edestä, kuinka hän ei lahjoittaisi meille kaikkea muutakin hänen kanssaan?',
        33: 'Kuka on syyttävä Jumalan valittuja? Jumala on se, joka julistaa vanhurskaaksi.',
        34: 'Kuka tuomitsee kadotukseen? Kristus Jeesus on se, joka on kuollut, onpa vielä herätettykin, ja hän on Jumalan oikealla puolella, ja hän myös rukoilee meidän edestämme.',
        35: 'Mikä erottaa meidät Kristuksen rakkaudesta? Tuska vai ahdistus, vai vaino, vai nälkä, vai alastomuus, vai vaara, vai miekka?',
        36: 'Niin kuin kirjoitettu on: "Sinun tähtesi meitä surmataan kaiken päivää, meitä pidetään teuraslampaina."',
        37: 'Mutta näissä kaikissa saamme jalon voiton hänen kauttaan, joka on meitä rakastanut.',
        38: 'Sillä olen varma siitä, ettei kuolema eikä elämä, eivät enkelit eivätkä henkivallat, eivät nykyiset eivätkä tulevaiset, eivät voimat,',
        39: 'ei korkeus eikä syvyys, eikä mikään muu luotu erota meitä Jumalan rakkaudesta, joka on Kristuksessa Jeesuksessa, meidän Herrassamme.',
    },
    9: {
        1: 'Sanon totuuden Kristuksessa, en valehtele – sen todistaa minulle omatuntoni Pyhässä Hengessä –',
        2: 'että minulla on suuri murhe ja jatkuva kipu sydämessäni.',
        3: 'Sillä minä soisin itse olevani kirottu pois Kristuksesta veljieni hyväksi, jotka ovat sukulaisiani lihan puolesta ja',
        4: 'ovat israelilaisia. Heidän on lapseus, kirkkaus, liitot, lain antaminen, jumalanpalvelus ja lupaukset.',
        5: 'Heidän ovat isät, ja heistä on Kristus lihan puolesta, hän, joka on yli kaiken, Jumala, ylistetty iankaikkisesti, aamen!',
        6: 'Mutta ei niin, että Jumalan sana olisi harhaan mennyt. Sillä eivät kaikki ne, jotka ovat Israelista, ole Israel,',
        7: 'eivät kaikki ole lapsia sen tähden, että ovat Aabrahamin siementä, vaan: "Iisakista kutsutaan sinulle siemen."',
        8: 'Se on: eivät ne, jotka lihan puolesta ovat lapsia, ole Jumalan lapsia, vaan lupauksen lapset, ne luetaan siemeneksi.',
        9: 'Sillä lupauksen sana oli tämä: "Minä palaan tähän aikaan, ja silloin Saaralla on poika."',
        10: 'Eikä ainoastaan näin ollut hänellä, vaan samoin Rebekallakin, joka oli tullut raskaaksi yhdestä, meidän isästämme Iisakista.',
        11: 'Ennen kuin kaksoset olivat syntyneetkään ja ennen kuin olivat tehneet mitään, hyvää tai pahaa, niin – että Jumalan valinnan mukainen edeltävä päätös pysyisi, ei tekojen tähden, vaan kutsujan tähden –',
        12: 'sanottiin hänelle: "Vanhempi on palveleva nuorempaa",',
        13: 'niin kuin on kirjoitettu: "Jaakobia minä rakastin, mutta Eesauta minä vihasin."',
        14: 'Mitä siis sanomme? Ei kaiketi Jumalassa ole vääryyttä? Ei ikinä!',
        15: 'Sillä Moosekselle hän sanoo: "Olen armollinen, kenelle olen armollinen, ja armahdan, ketä armahdan."',
        16: 'Se ei siis riipu siitä, joka tahtoo, eikä siitä, joka juoksee, vaan Jumalasta, joka on armollinen.',
        17: 'Sillä Raamattu sanoo faraolle: "Juuri sitä varten nostin sinut esiin, että näyttäisin sinussa voimani ja että nimeäni julistettaisiin kaikessa maassa."',
        18: 'Hän on siis armollinen, kenelle tahtoo, ja paaduttaa, kenet tahtoo.',
        19: 'Sinä kaiketi sanot minulle: "Miksi hän sitten vielä syyttää? Sillä kuka voi vastustaa hänen tahtoaan?"',
        20: 'Tosiaan, ihminen, mikä sinä olet väittelemään Jumalaa vastaan? Ei kaiketi saviastia sano valajalleen: "Miksi minusta tällaisen teit?"',
        21: 'Vai eikö savenvalajalla ole valta tehdä samasta saviseoksesta toinen astia jaloa, toinen halpaa käyttöä varten?',
        22: 'Mutta entä jos Jumala – vaikka tahtookin näyttää vihansa ja tehdä tiettäväksi voimansa – on suurella pitkämielisyydellä kärsinyt vihan astioita, jotka olivat valmiita hävitettäviksi,',
        23: 'ja on tehnyt sen saattaakseen kirkkautensa runsauden tiettäväksi laupeuden astioille, jotka hän on valmistanut edeltä kirkkauteen?',
        24: 'Sellaisiksi hän on kutsunut meidätkin, ei ainoastaan juutalaisista, vaan myös pakanoista,',
        25: 'niin kuin hän myös Hoosean kirjassa sanoo: "Minä olen kutsuva kansakseni sen, joka ei ollut minun kansani, ja rakkaakseni sen, joka ei ollut minun rakkaani.',
        26: 'On tapahtuva, että siinä paikassa, jossa heille on sanottu: \'Te ette ole minun kansani\', siinä heitä kutsutaan elävän Jumalan lapsiksi."',
        27: 'Mutta Jesaja huudahtaa Israelista: "Vaikka Israelin lapsia olisi määrältään kuin meren hiekkaa, pelastuu heistä vain jäännös.',
        28: 'Sillä sanansa Herra on toteuttava maan päällä vanhurskaudessa lopullisesti ja äkkiä."',
        29: 'Kuten Jesaja on myös ennustanut: "Ellei Herra Sebaot olisi jättänyt meille siementä, meidän olisi käynyt kuin Sodoman, ja olisimme Gomorran kaltaisia."',
        30: 'Mitä me siis sanomme? Että pakanat, jotka eivät tavoitelleet vanhurskautta, ottivat vastaan vanhurskauden, mutta sen vanhurskauden, joka tulee uskosta,',
        31: 'mutta Israel, joka tavoitteli vanhurskauden lakia, ei vanhurskauden lakia saavuttanut.',
        32: 'Minkä tähden? Sen tähden, ettei se tapahtunut uskosta, vaan ikään kuin lain teoista, sillä he loukkaantuivat loukkauskiveen,',
        33: 'niin kuin on kirjoitettu: "Katso, panen Siioniin loukkauskiven ja kompastuksen kallion, eikä kukaan, joka häneen uskoo, joudu häpeään."',
    },
    10: {
        1: 'Veljet, minä toivon sydämeni pohjasta ja rukoilen Jumalaa Israelin puolesta, että he pelastuisivat.',
        2: 'Sillä todistan heistä, että heillä on kiivaus Jumalan puoleen, mutta ei oikean tiedon mukaan,',
        3: 'sillä kun he eivät tunne Jumalan vanhurskautta, vaan yrittävät pystyttää omaa vanhurskauttaan, he eivät ole alistuneet Jumalan vanhurskauden alle.',
        4: 'Sillä Kristus on lain loppu, vanhurskaudeksi jokaiselle, joka uskoo.',
        5: 'Kirjoittaahan Mooses siitä vanhurskaudesta, joka tulee laista, että ihminen, joka sen täyttää, on siitä elävä.',
        6: 'Mutta se vanhurskaus, joka tulee uskosta, sanoo näin: "Älä sano sydämessäsi: Kuka nousee taivaaseen?" se on: tuomaan Kristusta alas,',
        7: 'tai: "Kuka astuu alas syvyyteen?" se on: nostamaan Kristusta kuolleista.',
        8: 'Mutta mitä se sanoo? "Sana on sinua lähellä, sinun suussasi ja sinun sydämessäsi." Se on se uskon sana, jota saarnaamme.',
        9: 'Sillä jos tunnustat suullasi Jeesuksen Herraksi ja uskot sydämessäsi, että Jumala on hänet kuolleista herättänyt, pelastut,',
        10: 'sillä sydämellä uskotaan vanhurskaudeksi, mutta suulla tunnustaen pelastutaan.',
        11: 'Sanoohan Raamattu: "Ei yksikään, joka uskoo häneen, joudu häpeään."',
        12: 'Tässä ei ole erotusta juutalaisen eikä kreikkalaisen välillä, sillä yksi ja sama on kaikkien Herra, rikas antaja kaikille, jotka häntä avuksi huutavat.',
        13: 'Sillä "jokainen, joka huutaa avuksi Herran nimeä, pelastuu."',
        14: 'Kuinka he sitten huutavat avukseen sitä, johon eivät usko? Kuinka he taas voivat uskoa siihen, josta eivät ole kuulleet? Mutta kuinka he voivat kuulla, ellei ole julistajaa?',
        15: 'Kuinka he julistavat, ellei heitä lähetetä? Niin kuin on kirjoitettu: "Kuinka suloiset ovat niiden jalat, jotka julistavat rauhaa ja tuovat hyvän sanoman!"',
        16: 'Mutta kaikki eivät ole olleet kuuliaisia evankeliumille. Sillä Jesaja sanoo: "Herra, kuka uskoo meidän saarnamme?"',
        17: 'Usko tulee siis saarnasta, mutta saarna Jumalan sanasta.',
        18: 'Mutta sanon: eivätkö he ole kuulleet? Kyllä ovat: "Heidän äänensä on kulkenut kaikkiin maihin, ja heidän sanansa maanpiirin ääriin."',
        19: 'Sanon: eikö Israelilla ole ollut siitä tietoa? Ensiksi jo Mooses sanoo: "Minä herätän teidän kiivautenne kansalla, joka ei ole kansa, ymmärtämättömällä kansalla teitä kiihotan."',
        20: 'Jesaja taas sanookin rohkeasti: "Minut ovat löytäneet ne, jotka eivät minua etsineet. Olen ilmestynyt niille, jotka eivät minua kysyneet."',
        21: 'Mutta Israelista hän sanoo: "Koko päivän olen ojentanut käsiäni tottelematonta ja vastaan sanovaa kansaa kohden."',
    },
    11: {
        1: 'Sanon siis: ei kai Jumala ole hylännyt kansaansa? Ei ikinä! Sillä olenhan minäkin israelilainen, Aabrahamin siementä, Benjaminin sukukuntaa.',
        2: 'Ei Jumala ole hylännyt kansaansa, jonka hän on edeltä tuntenut omakseen. Vai ettekö tiedä, mitä Raamattu sanoo Eliasta puhuessaan, kuinka hän Jumalan edessä syyttää Israelia:',
        3: '"Herra, he ovat tappaneet sinun profeettasi ja hajottaneet sinun alttarisi, ja minä yksin olen jäänyt jäljelle, ja he tavoittelevat minunkin henkeäni"?',
        4: 'Mutta mitä sanoo hänelle Jumalan vastaus? "Olen jättänyt itselleni seitsemäntuhatta miestä, jotka eivät ole notkistaneet polvea Baalille."',
        5: 'Samoin on nyt tänäkin aikana olemassa jäännös armon valinnan mukaan.',
        6: 'Mutta jos valinta on armosta, se ei ole enää teoista, sillä silloin armo ei enää olisi armo. Mutta jos se on teoista, se ei ole armoa, sillä muuten teko ei enää ole teko.',
        7: 'Miten siis on? Mitä Israel tavoittelee, sitä se ei ole saavuttanut, mutta valitut ovat sen saavuttaneet. Muut ovat paatuneet,',
        8: 'kuten on kirjoitettu: "Jumala on antanut heille uneliaisuuden hengen, silmät, etteivät näkisi, ja korvat, etteivät kuulisi, tähän päivään asti."',
        9: 'Ja Daavid sanoo: "Tulkoon heidän pöytänsä heille paulaksi, ansaksi, lankeemukseksi ja kostoksi,',
        10: 'tulkoot heidän silmänsä sokeiksi, etteivät näkisi, ja paina aina heidän selkäänsä kumaraan."',
        11: 'Sanon siis: eivät he kaiketi ole kompastuneet sitä varten, että lankeaisivat? Ei ikinä! Vaan heidän lankeemuksensa on pakanoille pelastukseksi, jotta he syttyisivät kateuteen.',
        12: 'Mutta jos heidän lankeemuksensa on maailmalle rikkaudeksi ja heidän tappionsa pakanoille rikkaudeksi, kuinka paljon enemmän heidän täyteytensä!',
        13: 'Teille, pakanoille, sanon: Koska minä olen pakanain apostoli, pidän virkani kunniassa,',
        14: 'sytyttääkseni, jos mahdollista, kiivauteen niitä, jotka ovat lihaani, ja pelastaakseni joitakin heistä.',
        15: 'Jos näet heidän hylkäämisensä on sovitukseksi maailmalle, mitä heidän armoon ottamisensa on muuta kuin elämä kuolleista?',
        16: 'Mutta jos uutisleipä on pyhä, niin on myös koko taikina, ja jos juuri on pyhä, niin ovat myös oksat.',
        17: 'Mutta jos muutamat oksista on taitettu pois ja sinä, joka olet metsäöljypuu, olet oksastettu oikeiden oksien joukkoon ja olet päässyt niiden kanssa osalliseksi öljypuun mehevästä juuresta,',
        18: 'niin älä ylpeile oksien rinnalla, mutta jos ylpeilet, niin et sinä kuitenkaan kannata juurta, vaan juuri sinua.',
        19: 'Ehkäpä sanot: "Nuo oksat taitettiin pois, jotta minut oksastettaisiin."',
        20: 'Oikein. Epäuskonsa tähden ne taitettiin pois, mutta sinä pysyt uskosi kautta. Älä ole ylpeä, vaan pelkää.',
        21: 'Sillä jos Jumala ei ole säästänyt luonnollisia oksia, hän ei ole säästävä sinuakaan.',
        22: 'Katso siis Jumalan hyvyyttä ja ankaruutta: Jumalan ankaruutta langenneita kohtaan, mutta hänen hyvyyttään sinua kohtaan, jos hänen hyvyydessään pysyt. Muuten sinutkin hakataan pois.',
        23: 'Mutta nuo toisetkin, jos eivät jää epäuskoonsa, tulevat oksastettaviksi, sillä Jumala on voimallinen oksastamaan ne jälleen.',
        24: 'Sillä jos sinut on leikattu luonnollisesta metsäöljypuusta ja vasten luontoa oksastettu jaloon öljypuuhun, kuinka paljoa ennemmin nämä luonnolliset oksat oksastetaan omaan öljypuuhunsa!',
        25: 'Sillä en tahdo, veljet – ettette olisi oman viisautenne varassa – pitää teitä tietämättöminä tästä salaisuudesta, että Israelia on kohdannut osaksi paatumus – aina siihen asti, kunnes pakanain täysi luku on tullut sisälle,',
        26: 'ja tällä tavalla kaikki Israel on pelastuva, kuten on kirjoitettu: "Siionista on tuleva pelastaja, hän poistaa jumalattoman menon Jaakobista.',
        27: 'Tämä on oleva minun liittoni heidän kanssaan, kun otan pois heidän syntinsä."',
        28: 'Evankeliumin kannalta he ovat tosin vihollisia teidän tähtenne, mutta valinnan kannalta he ovat rakastettuja isien tähden.',
        29: 'Sillä Jumala ei kadu armolahjojaan eikä kutsumistaan.',
        30: 'Samoin kuin te ennen olitte Jumalalle tottelemattomia, mutta nyt olette saaneet laupeuden näiden tottelemattomuuden kautta,',
        31: 'samoin nämäkin ovat nyt olleet tottelemattomia, että myös he teille tulleen armahtamisen kautta nyt saisivat laupeuden.',
        32: 'Sillä Jumala on sulkenut kaikki tottelemattomuuteen, että hän kaikkia armahtaisi.',
        33: 'Oi sitä Jumalan rikkauden ja viisauden ja tiedon syvyyttä! Kuinka tutkimattomat ovat hänen tuomionsa ja käsittämättömät hänen tiensä!',
        34: 'Sillä kuka on tuntenut Herran mielen? Tai kuka on ollut hänen neuvonantajansa?',
        35: 'Tai kuka on ensin antanut hänelle jotakin, joka olisi antajalle korvattava?',
        36: 'Sillä hänestä ja hänen kauttaan ja häntä varten on kaikki. Hänelle kunnia iankaikkisesti! Aamen.',
    },
    12: {
        1: 'Jumalan armahtavan laupeuden kautta kehotan siis teitä, veljet, antamaan ruumiinne eläväksi, pyhäksi, Jumalalle otolliseksi uhriksi. Se olkoon teidän järjellinen jumalanpalveluksenne.',
        2: 'Älkääkä mukautuko tämän maailmanajan mukaan, vaan muuttukaa mielenne uudistuksen kautta, tutkiaksenne, mikä on Jumalan tahto, mikä hyvää, otollista ja täydellistä.',
        3: 'Sillä sen armon kautta, mikä minulle on annettu, sanon teille jokaiselle, ettei tule ajatella itsestään enempää, kuin ajatella sopii, vaan ajatella kohtuullisesti sen uskonmäärän mukaan, minkä Jumala on kullekin jakanut.',
        4: 'Sillä niin kuin meillä yhdessä ruumiissa on monta jäsentä, mutta kaikilla jäsenillä ei ole sama tehtävä,',
        5: 'niin vaikka meitä on monta, olemme yksi ruumis Kristuksessa, mutta itse kukin olemme toistemme jäseniä.',
        6: 'Meillä on erilaisia armolahjoja sen armon mukaan, mitä meille on annettu. Jos jollakulla on profetoimisen lahja, käyttäköön sitä uskon mukaisesti;',
        7: 'jos virka, pitäköön virastaan vaarin; jos joku opettaa, olkoon uskollinen opettamisessaan;',
        8: 'jos kehottaa, kehottamisessaan; joka antaa, antakoon vakaasta sydämestä; joka on johtaja, johtakoon toimellisesti; joka laupeutta harjoittaa, tehköön sen iloiten.',
        9: 'Olkoon rakkaus vilpitön, kammotkaa pahaa, riippukaa hyvässä kiinni.',
        10: 'Olkaa veljellisessä rakkaudessa helläsydämiset toisianne kohtaan. Kunnioittamisessa asettakaa toinen itsenne edelle.',
        11: 'Intoon nähden älkää olko velttoja. Olkaa hengessä palavia, palvelkaa Herraa.',
        12: 'Olkaa toivossa iloiset, ahdistuksessa kärsivälliset, rukouksessa kestävät.',
        13: 'Pitäkää pyhien tarpeet ominanne. Harrastakaa vieraanvaraisuutta.',
        14: 'Siunatkaa vainoojianne, siunatkaa, älkääkä kirotko.',
        15: 'Iloitkaa iloitsevien kanssa, itkekää itkevien kanssa.',
        16: 'Olkaa keskenänne yksimieliset. Älkää korkeita havitelko, vaan tyytykää alhaisiin oloihin. Älkää olko omasta mielestänne viisaita.',
        17: 'Älkää kenellekään pahalla pahaa kostako. Ahkeroikaa sitä, mikä on hyvää kaikkien ihmisten edessä.',
        18: 'Jos on mahdollista ja mikäli teistä riippuu, eläkää rauhassa kaikkien ihmisten kanssa.',
        19: 'Älkää itse kostako, rakkaani, vaan antakaa sijaa vihalle, sillä kirjoitettu on: "Minun on kosto, minä olen maksava, sanoo Herra."',
        20: 'Vaan "jos vihamiehelläsi on nälkä, ruoki häntä, jos hänellä on jano, juota häntä, sillä näin tehden sinä kokoat tulisia hiiliä hänen päänsä päälle."',
        21: 'Älä anna pahan itseäsi voittaa, vaan voita sinä paha hyvällä.',
    },
    13: {
        1: 'Jokainen sielu olkoon alamainen niille valloille, joiden vallan alla hän on. Sillä ei ole esivaltaa muuten kuin Jumalalta. Vallat, jotka ovat, ovat Jumalan asettamia.',
        2: 'Sen tähden se, joka asettuu esivaltaa vastaan, nousee Jumalan säätämystä vastaan, mutta jotka nousevat vastaan, tuottavat itselleen tuomion.',
        3: 'Sillä hallitusmiehet eivät ole niiden pelkona, jotka tekevät hyvää, vaan niiden, jotka tekevät pahaa. Jos siis tahdot olla esivaltaa pelkäämättä, tee sitä, mikä on hyvää, ja sinä saat siltä kiitoksen.',
        4: 'Sillä se on Jumalan palvelija sinulle hyväksi. Mutta jos pahaa teet, pelkää, sillä se ei kanna miekkaa turhaan, koska se on Jumalan palvelija, kostaja sen rankaisemiseksi, joka pahaa tekee.',
        5: 'Siksi tulee olla alamainen, ei ainoastaan rangaistuksen tähden, vaan myös omantunnon tähden.',
        6: 'Sen tähden maksakaa myös veroja. Sillä he ovat Jumalan palvelijoita ja tekevät työtään juuri sitä varten.',
        7: 'Antakaa kaikille, mitä annettava on: kenelle vero, sille vero, kenelle tulli, sille tulli, kenelle pelko, sille pelko, kenelle kunnia, sille kunnia.',
        8: 'Älkää olko kenellekään mitään velkaa, muuta kuin että toisianne rakastatte, sillä se, joka toistansa rakastaa, on lain täyttänyt.',
        9: 'Sillä nämä: "Älä tee huorin, älä tapa, älä varasta, älä himoitse", ja mikä muu käsky tahansa, sisältyvät kaikki tähän sanaan: "Rakasta lähimmäistäsi kuin itseäsi."',
        10: 'Rakkaus ei tee lähimmäiselle mitään pahaa. Sen tähden rakkaus on lain täyttämys.',
        11: 'Tehkää tämä, koska tunnette tämän ajan, että on jo hetki teidän nousta unesta. Sillä pelastus on nyt meitä lähempänä kuin silloin, kun uskoon tulimme.',
        12: 'Yö on pitkälle kulunut, ja päivä on lähellä. Pankaamme sen tähden pois pimeyden teot, ja pukeutukaamme valkeuden aseisiin.',
        13: 'Vaeltakaamme säädyllisesti niin kuin päivällä, ei mässäillen ja juopotellen, ei haureudessa ja irstaudessa, ei riidassa ja kateudessa,',
        14: 'vaan pukekaa päällenne Herra Jeesus Kristus, älkääkä hellikö lihaanne niin, että himot heräävät.',
    },
    14: {
        1: 'Uskossa heikko ottakaa yhteyteenne väittelemättä mielipiteistä.',
        2: 'Joku toinen uskoo saavansa syödä kaikkea, mutta heikko syö vihanneksia.',
        3: 'Se, joka syö, älköön halveksiko sitä, joka ei syö, ja se, joka ei syö, älköön tuomitko sitä, joka syö, sillä Jumala on ottanut hänet omakseen.',
        4: 'Mikä sinä olet tuomitsemaan toisen palvelijan? Oman isäntänsä edessä hän seisoo tai kaatuu. Mutta hän on pysyvä pystyssä, sillä Herra on voimallinen pitämään hänet pystyssä.',
        5: 'Toinen pitää yhden päivän toista parempana, toinen pyhittää kaikki päivät. Olkoon jokainen omassa mielessään täysin varma.',
        6: 'Se, joka valikoi päiviä, valikoi Herralle. Se, joka syö, syö Herralle, sillä hän kiittää Jumalaa. Se, joka ei syö, on Herralle syömättä ja kiittää Jumalaa.',
        7: 'Sillä ei kukaan meistä elä itselleen, eikä kukaan kuole itselleen.',
        8: 'Jos elämme, elämme Herralle, ja jos kuolemme, kuolemme Herralle. Sen tähden, elimme tai kuolimme, olemme Herran omat.',
        9: 'Sillä sitä varten Kristus kuoli, heräsi eloon ja nousi kuolleista, että hän olisi sekä kuolleitten että elävien Herra.',
        10: 'Mutta sinä, minkä tähden tuomitset veljeäsi? Tai sinä toinen, minkä tähden halveksit veljeäsi? Sillä kaikki meidät asetetaan Jumalan tuomioistuimen eteen.',
        11: 'Sillä kirjoitettu on: "Niin totta kuin minä elän, sanoo Herra, minun edessäni on jokainen polvi notkistuva ja jokainen kieli ylistävä Jumalaa."',
        12: 'Niin on siis meidän jokaisen tehtävä Jumalalle tili itsestämme.',
        13: 'Älkäämme siis enää toisiamme tuomitko, vaan päättäkää pikemmin olla panematta veljenne eteen loukkauskiveä tai pahennusta.',
        14: 'Tiedän ja olen varma Herrassa Jeesuksessa, ettei mikään ole epäpyhää itsessään, vaan ainoastaan sille, joka pitää jotakin epäpyhänä, sille se on epäpyhää.',
        15: 'Mutta jos veljesi tulee murheelliseksi ruokasi tähden, niin et enää vaella rakkauden mukaan. Älä saata ruuallasi turmioon sitä, jonka edestä Kristus on kuollut.',
        16: 'Älkää siis antako sen hyvän, mikä teillä on, tulla häväistyksi,',
        17: 'sillä ei Jumalan valtakunta ole syömistä ja juomista, vaan vanhurskautta, rauhaa ja iloa Pyhässä Hengessä.',
        18: 'Se, joka tässä kohden palvelee Kristusta, on Jumalalle otollinen ja ihmisille kelvollinen.',
        19: 'Tavoitelkaamme siis sitä, mikä edistää rauhaa ja keskinäistä rakentumista.',
        20: 'Älä ruuan tähden turmele Jumalan työtä. Kaikki tosin on puhdasta, mutta sille ihmiselle, joka syö omaatuntoaan loukaten, se on pahaa.',
        21: 'Hyvä on olla lihaa syömättä ja viiniä juomatta sekä karttaa sitä, mistä veljesi loukkaantuu tai joutuu lankeemukseen tai tulee heikoksi.',
        22: 'Pidä itselläsi Jumalan edessä se usko, mikä sinulla on. Onnellinen on se, joka ei tuomitse itseään siitä, mitä pitää oikeana.',
        23: 'Mutta joka epäröi ja kuitenkin syö, on tuomittu, koska se ei tapahdu uskosta, sillä kaikki, mikä ei ole uskosta, on syntiä.',
    },
    15: {
        1: 'Mutta meidän, vahvojen, tulee kantaa heikkojen vajavuuksia, eikä olla itsellemme mieliksi.',
        2: 'Olkoon kukin meistä lähimmäiselleen mieliksi hänen parhaakseen, että hän rakentuisi.',
        3: 'Sillä ei Kristuskaan elänyt itselleen mieliksi, vaan niin kuin kirjoitettu on: "Niiden solvaukset, jotka sinua parjaavat, ovat sattuneet minuun."',
        4: 'Sillä kaikki, mikä ennen on kirjoitettu, on kirjoitettu meille opiksi, että meillä kärsivällisyyden ja Kirjoitusten lohdutuksen kautta olisi toivo.',
        5: 'Mutta kärsivällisyyden ja lohdutuksen Jumala suokoon teille, että olisitte yksimieliset keskenänne, Kristuksen Jeesuksen mukaan,',
        6: 'niin että yksimielisesti yhdestä suusta ylistäisitte Jumalaa ja meidän Herramme Jeesuksen Kristuksen Isää.',
        7: 'Ottakaa sen vuoksi toinen toisenne keskinäiseen yhteyteen, niin kuin Kristuskin on teidät luokseen ottanut, Jumalan kunniaksi.',
        8: 'Sillä minä sanon, että Kristus on tullut ympärileikattujen palvelijaksi Jumalan totuuden tähden vahvistaakseen isille annetut lupaukset,',
        9: 'mutta että pakanat laupeuden tähden ovat ylistäneet Jumalaa, kuten on kirjoitettu: "Sen tähden ylistän sinua pakanain keskellä ja laulan kiitosta sinun nimellesi."',
        10: 'Vielä hän sanoo: "Riemuitkaa, pakanat, hänen kansansa kanssa."',
        11: 'Ja taas: "Kiittäkää Herraa, kaikki pakanat, ja ylistäkööt häntä kaikki kansat."',
        12: 'Myös Jesaja sanoo: "On tuleva Iisain juurivesa, hän, joka nousee hallitsemaan pakanoita. Häneen pakanat panevat toivonsa."',
        13: 'Mutta toivon Jumala täyttäköön teidät uskoessanne kaikella ilolla ja rauhalla, että teillä olisi runsas toivo Pyhän Hengen voimassa.',
        14: 'Veljeni, minä itsekin olen varma teistä, että te itse olette täynnä hyvyyttä ja kaikkinaista tietoa, niin että myös kykenette neuvomaan toisianne.',
        15: 'Kuitenkin olen paikka paikoin jotenkin rohkeasti teille kirjoittanut muistuttaakseni teille näitä asioita sen armon tähden, jonka Jumala on minulle antanut',
        16: 'ollakseni Jeesuksen Kristuksen palvelija pakanoita varten toimittaakseni papillisesti Jumalan evankeliumin palvelusta, niin että pakanoista tulisi otollinen Pyhässä Hengessä pyhitetty uhri.',
        17: 'Minulla on siis kerskaukseni Kristuksessa Jeesuksessa palvellessani Jumalaa,',
        18: 'sillä minä en rohkene puhua mistään muusta kuin siitä, mitä Kristus on saattaakseen pakanat kuuliaisiksi kauttani vaikuttanut sanalla ja teolla,',
        19: 'tunnustekojen ja ihmeiden voimalla, Jumalan Hengen voimalla, niin että minä Jerusalemista ja sen ympäristöstä alkaen Illyrikoniin asti olen suorittanut Kristuksen evankeliumin julistamisen,',
        20: 'sillä tavoin, että olen pitänyt kunnianani olla julistamatta evankeliumia siellä, missä Kristuksen nimi on jo mainittu, etten rakentaisi toisen laskemalle perustukselle,',
        21: 'vaan kuten on kirjoitettu: "Ne, joille ei ole hänestä kerrottu, saavat nähdä hänet, ja ne, jotka eivät ole kuulleet, tajuavat."',
        22: 'Sen tähden olenkin niin usein ollut estetty tulemasta teidän luoksenne.',
        23: 'Mutta koska minulla nyt ei ole enää tilaa näissä paikkakunnissa ja kun jo monta vuotta olen halunnut tulla teidän luoksenne,',
        24: 'niin jos milloin menen Hispaniaan, tulen luoksenne, sillä toivon sieltä kautta matkustaessani näkeväni teidät ja teidän lähettävän minut sinne, kunhan ensin olen jonkin verran virkistynyt teistä.',
        25: 'Mutta nyt menen Jerusalemiin viemään pyhille avustusta.',
        26: 'Sillä Makedonia ja Akaia ovat nähneet hyväksi kerätä yhteisen lahjan niille Jerusalemin pyhille, jotka ovat köyhyydessä.',
        27: 'Niin he ovat nähneet hyväksi, ja he ovatkin sen heille velkaa, sillä jos pakanat ovat tulleet osallisiksi heidän hengellisistä aarteistaan, he ovat puolestaan velvollisia auttamaan heitä maallisilla.',
        28: 'Kun olen tämän suorittanut ja vienyt heille tämän hedelmän perille, lähden teidän kauttanne Hispaniaan.',
        29: 'Tiedän, että tullessani luoksenne tulen Kristuksen evankeliumin täydellinen siunaus mukanani.',
        30: 'Mutta kehotan teitä, veljet, Herramme Jeesuksen Kristuksen kautta ja Hengen rakkauden kautta taistelemaan kanssani rukouksissa ja puolestani rukoilemaan Jumalaa,',
        31: 'että pelastuisin Juudean epäuskoisilta ja että Jerusalemia varten tuomani avustus olisi pyhille otollinen,',
        32: 'niin että jos Jumala tahtoo, ilolla saapuisin luoksenne ja virkistyisin kanssanne.',
        33: 'Rauhan Jumala olkoon teidän kaikkien kanssa. Aamen.',
    },
    16: {
        1: 'Suosittelemme teille sisartamme Foibea, joka on Kenkrean seurakunnan palvelija,',
        2: 'että otatte hänet vastaan Herrassa, niin kuin pyhien sopii, ja autatte häntä kaikessa, missä hän teitä tarvitsee, sillä hän on ollut monelle avuksi ja jopa minulle.',
        3: 'Tervehtikää Priskaa ja Akylasta, työtovereitani Kristuksessa Jeesuksessa.',
        4: 'He ovat minun henkeni puolesta panneet oman kaulansa alttiiksi. En ainoastaan minä kiitä heitä, vaan myös kaikki pakanain seurakunnat.',
        5: 'Tervehtikää myös seurakuntaa, joka kokoontuu heidän kodissaan. Tervehtikää Epainetosta, rakasta veljeäni, joka on Aasian maakunnan ensi hedelmä Kristukselle.',
        6: 'Tervehtikää Mariaa, joka on nähnyt paljon vaivaa teidän hyväksenne.',
        7: 'Tervehtikää Andronikosta ja Juniaa, heimolaisiani ja vankeustovereitani, joilla on suuri maine apostolien keskuudessa ja jotka jo ennen minua ovat olleet Kristuksessa.',
        8: 'Tervehtikää Ampliatusta, rakasta veljeäni Herrassa.',
        9: 'Tervehtikää Urbanusta, työtoveriamme Kristuksessa, ja Stakysta, rakasta veljeäni.',
        10: 'Tervehtikää Apelleeta, koetuksen kestänyttä Kristuksessa. Tervehtikää Aristobuloksen perhekuntalaisia.',
        11: 'Tervehdys Herodionille, heimolaiselleni. Tervehdys Narkissuksen perhekuntalaisille, jotka ovat Herrassa.',
        12: 'Tervehtikää Tryfainaa ja Tryfosaa, jotka ovat nähneet vaivaa Herrassa. Tervehtikää Persistä, rakasta sisarta, joka on nähnyt paljon vaivaa Herrassa.',
        13: 'Tervehtikää Rufusta, valittua Herrassa, ja hänen äitiään, joka on kuin äiti minullekin.',
        14: 'Tervehtikää Asynkritosta, Flegonia, Hermestä, Patrobasta, Hermasta ja veljiä, jotka ovat heidän kanssaan.',
        15: 'Tervehtikää Filologosta ja Juliaa, Nereusta ja hänen sisartaan ja Olympasta ja kaikkia pyhiä, jotka ovat heidän kanssaan.',
        16: 'Tervehtikää toisianne pyhällä suudelmalla. Kaikki Kristuksen seurakunnat tervehtivät teitä.',
        17: 'Mutta kehotan teitä, veljet, pitämään silmällä niitä, jotka saavat aikaan erimielisyyttä ja pahennusta vastoin sitä oppia, jonka te olette saaneet. Vetäytykää pois heistä.',
        18: 'Sillä sellaiset eivät palvele Herraamme Kristusta, vaan omaa vatsaansa, ja he pettävät mielistelevillä sanoilla ja ylistävillä puheilla vilpittömien sydämet.',
        19: 'Onhan teidän kuuliaisuutenne tullut kaikkien tietoon. Niinpä iloitsen teistä, mutta tahtoisin teidän olevan viisaita hyvään, mutta puhtaita pahaan nähden.',
        20: 'Mutta rauhan Jumala on pian musertava saatanan jalkojenne alle. Herramme Jeesuksen armo olkoon kanssanne. Aamen.',
        21: 'Teitä tervehtivät Timoteus, työtoverini, ja heimolaiseni Lukius, Jaason ja Soosipater.',
        22: 'Minä Tertius, joka olen kirjoittanut tämän kirjeen, tervehdin teitä Herrassa.',
        23: 'Gaius, minun ja koko seurakunnan majoittaja, tervehtii teitä. Erastus, kaupungin varainhoitaja, ja veli Quartus tervehtivät teitä.',
        24: 'Herramme Jeesuksen Kristuksen armo olkoon teidän kanssanne. Aamen.',
        25: 'Mutta hänen, joka voi teitä vahvistaa minun evankeliumini ja Jeesuksen Kristuksen saarnan mukaan, sen ilmoitetun salaisuuden mukaan, joka kautta ikuisten aikojen on ollut ilmoittamatta,',
        26: 'mutta joka nyt on saatettu julki ja profeetallisten Kirjoitusten kautta iankaikkisen Jumalan käskystä tehty tiettäväksi kaikille kansoille uskon kuuliaisuuden aikaansaamiseksi,',
        27: 'Jumalan, ainoan viisaan, olkoon kunnia Jeesuksen Kristuksen kautta iankaikkisesti. Aamen.',
    },
}
